#include <future>
#include <iostream>
#include <vector>

int main() {
    int n = 0;
    if (!(std::cin >> n)) return 1;
    if (n < 1 || n > 1000) return 1;
    std::vector<long long> values;
    for (int i = 0; i < n; i++) {
        long long value = 0;
        if (!(std::cin >> value)) return 1;
        if (value < -10000 || value > 10000) return 1;
        values.push_back(value);
    }
    std::future<long long> task = std::async(std::launch::async, [&values] {
        long long total = 0;
        for (long long value : values) total += value;
        return total;
    });
    std::cout << task.get() << std::endl;
    return 0;
}
